const cardKeysService=['service-seo','service-paid','service-social','service-ecommerce','service-content','service-events','service-analytics'];
const cardKeysPortfolio=['case-ecommerce','case-seo','case-paid','case-events','case-brand','case-education'];
function annotate(file,cls,keys){
  if(!fs.existsSync(file))return;
  let h=fs.readFileSync(file,'utf8'),i=0;
  const re=new RegExp('<article class="'+cls+'"','g');
  h=h.replace(re,m=>{const key=keys[i++];return key?'<article class="'+cls+'" data-card-key="'+key+'"':m;});
  fs.writeFileSync(file,h);
}
