function insertBeforeFooter(file,marker,html){
 if(!fs.existsSync(file))return;
 let h=fs.readFileSync(file,'utf8');
 if(h.includes(marker))return;
 h=h.replace(/<footer\b/i,html+'<footer');
 fs.writeFileSync(file,h);
}
