const siteJsFile=path.join(root,'assets','site.js');
let js=fs.readFileSync(siteJsFile,'utf8');
if(!js.includes('__RASSMIY_CARDS_V60__')){
js+=`
;(()=>{
 if(window.__RASSMIY_CARDS_V60__)return;window.__RASSMIY_CARDS_V60__=true;
 const lang=(document.documentElement.lang||'ar').startsWith('ar')?'ar':'en';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 const field=(c,n)=>c[n+'_'+lang]||c[n+'_en']||c[n+'_ar']||'';
 const renderService=(c)=>'<article class="service-card is-clickable-card" data-card-key="'+esc(c.id)+'" data-card-link="'+esc(field(c,'cta_url'))+'">'+(c.image?'<img class="editable-card-media" src="'+esc(c.image)+'" alt="'+esc(field(c,'alt')||field(c,'title'))+'">':'')+(field(c,'eyebrow')?'<div class="card-eyebrow">'+esc(field(c,'eyebrow'))+'</div>':'')+'<h3>'+esc(field(c,'title'))+'</h3><p>'+esc(field(c,'description'))+'</p>'+(field(c,'metric')?'<div class="card-metric">'+esc(field(c,'metric'))+'</div>':'')+(field(c,'cta_label')?'<a class="link" href="'+esc(field(c,'cta_url')||'#')+'">'+esc(field(c,'cta_label'))+'</a>':'')+'</article>';
 const renderCase=(c)=>'<article class="case-card is-clickable-card" data-card-key="'+esc(c.id)+'" data-card-link="'+esc(field(c,'cta_url'))+'">'+(c.image?'<img class="editable-card-media" src="'+esc(c.image)+'" alt="'+esc(field(c,'alt')||field(c,'title'))+'">':'')+(field(c,'eyebrow')?'<div class="card-eyebrow">'+esc(field(c,'eyebrow'))+'</div>':'')+'<h3>'+esc(field(c,'title'))+'</h3><p>'+esc(field(c,'description'))+'</p>'+(field(c,'metric')?'<div class="card-metric">'+esc(field(c,'metric'))+'</div>':'')+(field(c,'cta_label')?'<a class="case-link" href="'+esc(field(c,'cta_url')||'#')+'">'+esc(field(c,'cta_label'))+'</a>':'')+'</article>';
 async function hydrate(){
  try{
   const r=await fetch('/api/cards',{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)return;
   const data=await r.json(),cards=(data.cards||[]).filter(c=>c.enabled!==false).sort((a,b)=>(a.order||0)-(b.order||0));
   for(const collection of ['service','portfolio']){
    const selector=collection==='service'?'.service-card':'.case-card';
    const existing=[...document.querySelectorAll(selector)];
    if(!existing.length)continue;
    const parent=existing[0].parentElement;
    const list=cards.filter(c=>c.collection===collection);
    const byId=new Map(list.map(c=>[c.id,c]));
    existing.forEach(el=>{const id=el.dataset.cardKey;if(id&&!byId.has(id))el.hidden=true;});
    for(const c of list){
      const old=document.querySelector(selector+'[data-card-key="'+CSS.escape(c.id)+'"]');
      const wrap=document.createElement('div');wrap.innerHTML=(collection==='service'?renderService(c):renderCase(c));
      const fresh=wrap.firstElementChild;
      if(old)old.replaceWith(fresh);else parent.appendChild(fresh);
    }
   }
   document.dispatchEvent(new CustomEvent('rassmiy:cards-hydrated'));
  }catch(e){console.warn('Cards hydration skipped',e);}
 }
 document.readyState==='loading'?document.addEventListener('DOMContentLoaded',hydrate):hydrate();
})();
`;
fs.writeFileSync(siteJsFile,js);
}

